import{_ as e,o as i,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Extremidades y trauma","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/limbs-and-trauma.md","filePath":"es/guide/combat/limbs-and-trauma.md"}'),t={name:"es/guide/combat/limbs-and-trauma.md"};function r(l,a,s,d,c,u){return i(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="limbs-and-trauma" tabindex="-1">Extremidades y trauma <a class="header-anchor" href="#limbs-and-trauma" aria-label="Enlace permanente a &quot;Extremidades y trauma&quot;">​</a></h1><ul><li><strong>Estado del diseño:</strong> Aceptado para la separación y Experimental para la integridad local; Propuesto para lesiones ampliadas.</li><li><strong>Implementación:</strong> Combate cuerpo a cuerpo natural y estado local de Stage 2A; consecuencia funcional del escudo aplazada.</li><li><strong>Disponibilidad:</strong> aquí no se establece ningún comportamiento nuevo en vivo; no se ha inspeccionado la configuración actual.</li><li><strong>Verificación:</strong> documentación revisada el 2026-10-08; sin nueva prueba de juego. El alcance de la evidencia existente figura en <a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">estado del combate</a>.</li></ul><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>La salud global, la integridad local y el estado de la armadura son independientes.</li><li>Siete regiones corporales pueden registrar daño local; Disabled no significa amputación automática.</li><li>Registrar una lesión no establece todas sus consecuencias funcionales; la curación ordinaria no equivale a recuperarse por completo del trauma.</li></ul><h2 id="health-is-not-the-whole-story" tabindex="-1">La salud no lo cuenta todo <a class="header-anchor" href="#health-is-not-the-whole-story" aria-label="Enlace permanente a &quot;La salud no lo cuenta todo&quot;">​</a></h2><p>La salud global sigue determinando la supervivencia. La integridad local describe el estado de Head, Neck, Torso, Left Arm, Right Arm, Left Leg y Right Leg. Un golpe acertado puede dañar la salud y la región que realmente alcanza. El estado de la armadura es una tercera cuestión independiente; el futuro sangrado es una condición propuesta, no otro nombre para el trauma local.</p><p>Una región pasa de Healthy por Wounded, Injured y Severe hasta Disabled. En el diseño, Disabled significa pérdida de función, no amputación automática. El experimento actual registra estos estados; todavía no hace que una pierna lesionada ralentice el movimiento ni que una cabeza incapacitada cause muerte instantánea. La pérdida del escudo, que pasa a la mochila, es una intención aprobada, pero sigue aplazada.</p><h2 id="recovery-is-still-an-experiment" tabindex="-1">La recuperación sigue siendo un experimento <a class="header-anchor" href="#recovery-is-still-an-experiment" aria-label="Enlace permanente a &quot;La recuperación sigue siendo un experimento&quot;">​</a></h2><p>La curación ordinaria de salud no repara automáticamente la integridad local. El Lab usa estados y reinicios limitados a la sesión, que no constituyen un sistema médico definitivo. La curación, el control del sangrado, la estabilización y las lesiones duraderas necesitan un diseño posterior. No hay que asumir que una venda ya repara cualquier tipo de daño.</p><p><a href="/Syrolands-Public/es/game-design/combat/body-regions.html">Modelo corporal y ciclo de vida exactos</a> · <a href="/Syrolands-Public/es/game-design/combat/damage.html">Política de daño y trauma</a> · <a href="/Syrolands-Public/es/game-design/combat/disability.html">Límites de la incapacitación</a>.</p><p><a href="/Syrolands-Public/es/guide/combat/overview.html">Volver al resumen de combate</a></p>',11)])])}const g=e(t,[["render",r]]);export{p as __pageData,g as default};
